package ru.neverland.townysieges;
import java.util.*;
import org.bukkit.*;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.ServicePriority;
import ru.neverland.core.*;
import ru.neverland.townysieges.api.SiegesCampSupplyApi;

/** Complete bundles only: physical city deliveries first, otherwise a receipted Army debit. */
public final class CampSupplies implements SiegesCampSupplyApi,Listener {
    public record Settings(boolean enabled,Map<String,Long> cargo,Map<String,Long> army){public Settings{cargo=CampSupplyLedger.items(cargo);army=Map.copyOf(army);if(cargo.isEmpty()||army.isEmpty()||!Set.of("food","water","metal","materials","wood","stone","knowledge","influence").containsAll(army.keySet())||army.values().stream().anyMatch(n->n<1||n>1_000_000_000L))throw new IllegalArgumentException("Некорректный расход лагеря");}public static Settings load(ConfigurationSection c){if(c.getRoot()!=null)c.getRoot().options().copyDefaults(true);var cargo=new HashMap<String,Long>();var army=new HashMap<String,Long>();var s=c.getConfigurationSection("camp-supplies.cargo-per-minute");if(s==null)cargo.putAll(Map.of("BREAD",2L,"IRON_INGOT",1L));else for(String k:s.getKeys(false))cargo.put(k,SafeYaml.longValue(s,k));s=c.getConfigurationSection("camp-supplies.army-per-minute");if(s==null)army.putAll(Map.of("food",1000L,"metal",250L));else for(String k:s.getKeys(false))army.put(k,new java.math.BigDecimal(s.getString(k)).movePointRight(3).longValueExact());return new Settings(c.getBoolean("camp-supplies.enabled",true),cargo,army);}}
    private final NeverLandTownySiegesPlus plugin;private final RaidController raids;private final CampSupplyLedger ledger;private Settings settings;
    public CampSupplies(NeverLandTownySiegesPlus plugin,RaidController raids,ConfigurationSection c)throws Exception{this.plugin=plugin;this.raids=raids;settings=Settings.load(c);ledger=new CampSupplyLedger(plugin.getDataFolder().toPath().resolve("camp-supplies.yml"));Bukkit.getServicesManager().register(SiegesCampSupplyApi.class,this,plugin,ServicePriority.Normal);Bukkit.getPluginManager().registerEvents(this,plugin);}
    public void reload(Settings next){settings=next;}
    private void ready(){if(!ledger.writable()||SuiteState.frozen(plugin.getName()))throw new IllegalArgumentException("Снабжение лагеря сейчас приостановлено");}
    public Map<String,Object> depot(UUID town){try(var g=SuiteState.guard()){ready();var c=plugin.camps().camp(town);if(c==null||!plugin.camps().active(c.attacker(),c.defender()))return Map.of();return Map.of("id","raid_camp:"+c.id(),"name","Военный склад осадного лагеря","icon","CAMPFIRE","world",c.world(),"x",c.x(),"y",c.y(),"z",c.z());}}
    public boolean allowsTransit(UUID town,UUID world,double x,double y,double z){try(var g=SuiteState.guard()){ready();var c=plugin.camps().camp(town);return Double.isFinite(x)&&Double.isFinite(y)&&Double.isFinite(z)&&c!=null&&c.world().equals(world)&&plugin.camps().active(c.attacker(),c.defender())&&Math.hypot(x-c.x(),z-c.z())<=64&&Math.abs(y-c.y())<=32;}}
    public ItemStack[] stock(UUID town){try(var g=SuiteState.guard()){ready();ItemStack[] out=new ItemStack[54];int i=0;for(var e:new TreeMap<>(ledger.state().stock().getOrDefault(town,Map.of())).entrySet()){long n=e.getValue();while(n>0){int size=(int)Math.min(64,n);out[i++]=new ItemStack(Material.valueOf(e.getKey()),size);n-=size;}}return out;}}
    private static Map<String,Long> cargo(ItemStack[] items){var amounts=new HashMap<String,Long>();for(ItemStack i:items){if(i==null||i.getType().isAir())continue;if(i.hasItemMeta()||i.getAmount()<1||i.getAmount()>i.getMaxStackSize())throw new IllegalArgumentException("Лагерь принимает обычный хлеб и обычные железные слитки");amounts.merge(i.getType().name(),(long)i.getAmount(),Math::addExact);}if(amounts.isEmpty())throw new IllegalArgumentException("Пустой груз");return CampSupplyLedger.items(amounts);}
    public boolean hasReceipt(UUID town,UUID shipment){try(var g=SuiteState.guard()){ready();var r=ledger.state().receipts().get(shipment);if(r!=null&&!r.town().equals(town))throw new IllegalArgumentException("Груз другого города");return r!=null;}}
    public boolean received(UUID town,UUID shipment,UUID camp,ItemStack[] cargo){try(var g=SuiteState.guard()){ready();var old=ledger.state().receipts().get(shipment);if(old==null)return false;var expected=new CampSupplyLedger.Receipt(town,camp,cargo(cargo));if(!old.equals(expected))throw new IllegalArgumentException("Квитанция груза не совпадает");return true;}}
    public boolean receive(UUID town,UUID shipment,UUID camp,ItemStack[] cargo)throws Exception{try(var g=SuiteState.guard()){ready();if(received(town,shipment,camp,cargo))return true;var c=plugin.camps().camp(town);if(c==null||!c.id().equals(camp)||!plugin.camps().active(c.attacker(),c.defender()))return false;var amounts=cargo(cargo);boolean ok=ledger.receive(shipment,new CampSupplyLedger.Receipt(town,camp,amounts));if(ok)AuditTrail.record(plugin,"delivery",shipment.toString(),"RAID_SUPPLY","DELIVERED",AuditRecord.Party.system(),AuditTrail.town(town),AuditTrail.town(town),"",amounts.values().stream().mapToLong(Long::longValue).sum(),"","camp="+camp+"; cargo="+amounts);return ok;}}
    @SuppressWarnings("unchecked") private Map<String,Long> reserves(UUID town)throws Exception{return(Map<String,Long>)ApiServices.require("NeverLandTownyArmy","ru.neverland.townyarmy.api.TownyArmyApi","reserves").invoke("reserves",new Class<?>[]{UUID.class},town);}
    public boolean available(UUID town){if(!settings.enabled())return true;try{ready();return CampSupplyLedger.covers(ledger.state().stock().getOrDefault(town,Map.of()),settings.cargo())||CampSupplyLedger.covers(reserves(town),settings.army());}catch(Exception ex){return false;}}
    public void declaration(UUID town){if(!available(town))throw new IllegalArgumentException("Для рейда нужны запасы лагеря: доставьте хлеб и железные слитки через /t logistics или пополните военные запасы /t army");}
    public boolean supplied(RaidStore.Raid war){if(!settings.enabled())return true;long minute=Math.max(0,(System.currentTimeMillis()-war.starts())/60_000L);var f=ledger.state().funding().get(war.id());return ledger.writable()&&f!=null&&f.state().equals("PAID")&&f.minute()==minute&&f.town().equals(war.attacker());}
    public void pulse(){if(!settings.enabled()||!ledger.writable())return;for(var war:raids.declarations())if(war.fighting(System.currentTimeMillis())&&!supplied(war))try{fund(war);}catch(Exception ex){plugin.getLogger().warning("Снабжение рейда "+war.id()+" ожидает проверки: "+ex.getMessage());}}
    private void fund(RaidStore.Raid war)throws Exception{ready();long minute=Math.max(0,(System.currentTimeMillis()-war.starts())/60_000L);var old=ledger.state().funding().get(war.id());if(old!=null&&old.state().equals("PLANNED")){completeArmy(old);old=ledger.state().funding().get(war.id());if(old!=null&&old.state().equals("PLANNED"))return;}if(old!=null&&old.minute()>=minute)return;var stock=ledger.state().stock().getOrDefault(war.attacker(),Map.of());if(CampSupplyLedger.covers(stock,settings.cargo())){var f=new CampSupplyLedger.Funding(war.id(),war.attacker(),minute,"CARGO","PAID",settings.cargo());ledger.funding(f,true);audit(f);return;}var f=new CampSupplyLedger.Funding(war.id(),war.attacker(),minute,"ARMY","PLANNED",settings.army());ledger.funding(f,false);completeArmy(f);}
    private void completeArmy(CampSupplyLedger.Funding f)throws Exception{boolean applied=Boolean.TRUE.equals(ApiServices.require("NeverLandTownyArmy","ru.neverland.townyarmy.api.TownyArmyApi","consumeRaidSupplies").invoke("consumeRaidSupplies",new Class<?>[]{UUID.class,UUID.class,Map.class},f.town(),f.id(),f.cost()));if(applied){ledger.funding(f.paid(),false);audit(f.paid());}else ledger.clear(f.war());}
    private void audit(CampSupplyLedger.Funding f){AuditTrail.record(plugin,"consume",f.id().toString(),"RAID_SUPPLY","CONSUMED",AuditRecord.Party.system(),AuditTrail.town(f.town()),AuditRecord.Party.system(),"",0,"","raid="+f.war()+"; minute="+f.minute()+"; source="+f.source()+"; cost="+f.cost());}
    private String armyDescription(){return settings.army().entrySet().stream().sorted(Map.Entry.comparingByKey()).map(e->switch(e.getKey()){case "food"->"Еда";case "water"->"Вода";case "metal"->"Металл";case "materials"->"Материалы";case "wood"->"Древесина";case "stone"->"Камень";case "knowledge"->"Знания";case "influence"->"Влияние";default->e.getKey();}+": "+java.math.BigDecimal.valueOf(e.getValue(),3).stripTrailingZeros().toPlainString()).collect(java.util.stream.Collectors.joining(", "));}
    private static final class View implements InventoryHolder{final UUID owner;Inventory inventory;View(UUID owner){this.owner=owner;}public Inventory getInventory(){return inventory;}}
    public void open(Player p){try(var g=SuiteState.guard()){ready();var town=SiegeService.town(p.getUniqueId());if(town==null)throw new IllegalArgumentException("Вы не состоите в городе");View v=new View(p.getUniqueId());v.inventory=MenuStyle.inventory(plugin,v,27,"Снабжение осадного лагеря");var stock=ledger.state().stock().getOrDefault(town.getUUID(),Map.of());v.inventory.setItem(11,SiegeMenu.item(Material.BREAD,"Запасы лагеря",List.of("Хлеб: "+stock.getOrDefault("BREAD",0L),"Железные слитки: "+stock.getOrDefault("IRON_INGOT",0L),"Грузовой маршрут: /t logistics","Назначение: военный склад осадного лагеря","Нужны обычные предметы без названия")));v.inventory.setItem(15,SiegeMenu.item(Material.CLOCK,"Расход каждую минуту боя",List.of("Хлеб: "+settings.cargo().getOrDefault("BREAD",0L)+", железо: "+settings.cargo().getOrDefault("IRON_INGOT",0L),"Если груза не хватает — военные запасы:",armyDescription(),"Без снабжения TNT и захват приостановлены","Запасы сохраняются при потере лагеря")));v.inventory.setItem(22,SiegeMenu.item(Material.ARROW,"Назад",List.of()));p.openInventory(v.inventory);}}
    @EventHandler public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof View v))return;e.setCancelled(true);if(e.getWhoClicked() instanceof Player p&&v.owner.equals(p.getUniqueId())&&e.getRawSlot()==22)SuiteScheduler.player(plugin,p,x->p.performCommand("sieges"));}
    @EventHandler public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof View)e.setCancelled(true);}
}
